//
//  ThemeCatalogLoader.swift
//  GuacTerm
//
//  Reads the vendored iTerm2 color schemes from the bundled Themes.json.
//
//  The JSON is generated by scripts/generate-themes.py and holds one object per
//  scheme:
//
//      {"id":"3024-night","name":"3024 Night","bg":"#090300",
//       "fg":"#BBBBBB","cursor":"#BBBBBB","ansi":["#090300", ... 16 values]}
//
//  Parsing happens once, lazily, and never throws at the call site: a missing or
//  damaged resource degrades the catalog to the two signature themes instead of
//  crashing the app or leaving the picker empty.
//

import Foundation

/// One element of Themes.json, before it becomes a `TerminalTheme`.
private struct VendoredTheme: Decodable {
    let id: String
    let name: String
    let bg: String
    let fg: String
    let cursor: String
    let ansi: [String]
}

enum ThemeCatalogLoader {

    /// Number of colors every scheme must carry (ANSI 0-15).
    private static let ansiCount = 16

    private static let resourceName = "Themes"
    private static let resourceExtension = "json"

    /// The vendored schemes, sorted by name.
    ///
    /// `static let` is lazily initialised exactly once and is thread-safe, which
    /// is all the concurrency handling Swift 6 needs here: `[TerminalTheme]` is
    /// `Sendable`, so no locking or `@MainActor` hops are involved.
    static let themes: [TerminalTheme] = load()

    // MARK: - Loading

    private static func load() -> [TerminalTheme] {
        guard let url = Bundle.main.url(
            forResource: resourceName,
            withExtension: resourceExtension
        ) else {
            NSLog(
                "GuacTerm: %@.%@ is not in the app bundle; offering only the built-in themes.",
                resourceName, resourceExtension
            )
            return []
        }

        let decoded: [VendoredTheme]
        do {
            let data = try Data(contentsOf: url)
            decoded = try JSONDecoder().decode([VendoredTheme].self, from: data)
        } catch {
            NSLog(
                "GuacTerm: could not read %@.%@ (%@); offering only the built-in themes.",
                resourceName, resourceExtension, String(describing: error)
            )
            return []
        }

        var seenIDs = Set<String>()
        let themes = decoded
            .compactMap { theme(from: $0) }
            .filter { seenIDs.insert($0.id).inserted }
            .sorted { nameOrder($0, $1) }

        if themes.count != decoded.count {
            NSLog(
                "GuacTerm: skipped %ld unusable entries in %@.%@.",
                decoded.count - themes.count, resourceName, resourceExtension
            )
        }
        if themes.isEmpty {
            NSLog(
                "GuacTerm: %@.%@ holds no usable schemes; offering only the built-in themes.",
                resourceName, resourceExtension
            )
        }
        return themes
    }

    /// Converts one decoded entry, rejecting anything that would make the UI
    /// draw garbage (empty id, wrong color count, malformed hex).
    private static func theme(from entry: VendoredTheme) -> TerminalTheme? {
        guard !entry.id.isEmpty, !entry.name.isEmpty else { return nil }
        guard entry.ansi.count == ansiCount else { return nil }
        guard isHexColor(entry.bg), isHexColor(entry.fg), isHexColor(entry.cursor) else {
            return nil
        }
        guard entry.ansi.allSatisfy(isHexColor) else { return nil }

        return TerminalTheme(
            id: entry.id,
            name: entry.name,
            isLight: isLight(background: entry.bg),
            background: entry.bg,
            foreground: entry.fg,
            cursor: entry.cursor,
            ansi: entry.ansi
        )
    }

    // MARK: - Ordering

    /// Matches the order scripts/generate-themes.py writes: case-insensitive by
    /// name, then by the exact name and id so the sort is a total order.
    private static func nameOrder(_ lhs: TerminalTheme, _ rhs: TerminalTheme) -> Bool {
        let left = lhs.name.lowercased()
        let right = rhs.name.lowercased()
        if left != right { return left < right }
        if lhs.name != rhs.name { return lhs.name < rhs.name }
        return lhs.id < rhs.id
    }

    // MARK: - Colors

    /// True for `#RRGGBB` (case-insensitive; the generator always writes upper).
    private static func isHexColor(_ text: String) -> Bool {
        rgbComponents(text) != nil
    }

    /// `#RRGGBB` -> (red, green, blue) as 0...255, or nil when malformed.
    private static func rgbComponents(_ text: String) -> (Int, Int, Int)? {
        var digits = Substring(text.trimmingCharacters(in: .whitespacesAndNewlines))
        if digits.first == "#" { digits = digits.dropFirst() }
        guard digits.count == 6, let value = UInt32(digits, radix: 16) else { return nil }
        return (
            Int((value >> 16) & 0xFF),
            Int((value >> 8) & 0xFF),
            Int(value & 0xFF)
        )
    }

    /// A background this bright wants dark text, so the window gets a light
    /// chrome: WCAG relative luminance above 0.5.
    private static func isLight(background hex: String) -> Bool {
        relativeLuminance(of: hex) > 0.5
    }

    /// WCAG relative luminance, 0 (black) ... 1 (white).
    private static func relativeLuminance(of hex: String) -> Double {
        guard let (red, green, blue) = rgbComponents(hex) else { return 0 }
        return 0.2126 * linearComponent(red)
            + 0.7152 * linearComponent(green)
            + 0.0722 * linearComponent(blue)
    }

    /// Undoes the sRGB transfer function for one 0...255 channel.
    private static func linearComponent(_ value: Int) -> Double {
        let channel = Double(value) / 255
        return channel <= 0.04045
            ? channel / 12.92
            : pow((channel + 0.055) / 1.055, 2.4)
    }
}
